  function cleanWord(text) {
    return String(text).replace(DECOR, '').replace(/\s+/g, ' ').trim();
  }

  function normalize(text) {
    return cleanWord(text).replace(ZALIK, 'ذلك');
  }

  function wordsOf(verse) {
    if (!verse || !Array.isArray(verse.words)) return [];
    const out = [];
    for (const w of verse.words) {
      if (!w || w.char_type_name !== 'word') continue;
      const raw = w.text_imlaei_simple
        || (w.text_qpc_hafs ? w.text_qpc_hafs.replace(HARAKAT, '') : '');
      if (!raw) continue;
      const t = cleanWord(raw);
      if (t) out.push(t);
    }
    return out;
  }

  function get(surahId, ayah, words) {
    const ex = EXCEPTIONS[`${surahId}:${ayah}`];
    if (typeof ex === 'string') return ex;
    if (!words || !words.length) return '';
    const cleaned = [];
    for (const w of words) {
      const c = cleanWord(w);
      if (c) cleaned.push(c);
    }
    if (!cleaned.length) return '';
    const n = typeof ex === 'number' ? ex : DEFAULT_COUNT;
    return normalize(cleaned.slice(0, n).join(' '));
  }

  function getFromVerse(surahId, ayah, verse) {
    return get(surahId, ayah, wordsOf(verse));
  }

  return { EXCEPTIONS, normalize, wordsOf, get, getFromVerse };
